using namespace std;
​
int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> segs(n);

    // 读入数据并保证区间为 [min, max]
    for (int i = 0; i < n; i++) {
        int a, b;
        char comma;
        cin >> a >> comma >> b;
        segs[i] = {a, b};
    }

    // 按起点排序，方便合并
    sort(segs.begin(), segs.end());
​
    // 合并区间
    vector<pair<int, int>> merged;
    pair<int, int> cur = segs[0];
​
    for (int i = 1; i < n; i++) {
        if (segs[i].first <= cur.second) {
            cur.second = max(cur.second, segs[i].second);
        } else {
            merged.push_back(cur);
            cur = segs[i];
        }
    }
    merged.push_back(cur);

    // 计算最少覆盖线段数
    int totalCount = 0;
​
    for (auto [L, R] : merged) {
        int count = 0;
        int current = L;
​
        while (current < R) {
            int best = current;
            // 在所有能覆盖 `current` 的线段中，选终点最远的
            for (auto [start, end] : segs) {
                if (start <= current && end > best) {
                    best = end;
                }
            }

            // 如果无法扩展，则表示输入数据不可完全覆盖
            if (best == current) {
                cout << -1 << endl;
                return 0;
            }

            count++;
            current = best;
        }

        totalCount += count;
    }
​
    cout << totalCount << endl;
    return 0;
}
