import java.util.*;
​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        scanner.nextLine(); // 读取换行符
​
        List<int[]> segments = new ArrayList<>();
​
        // 读入数据
        for (int i = 0; i < n; i++) {
            String[] parts = scanner.nextLine().split(",");
            int start = Integer.parseInt(parts[0]);
            int end = Integer.parseInt(parts[1]);
            segments.add(new int[]{start, end});
        }
​
        // 按起点排序
        segments.sort((a, b) -> Integer.compare(a[0], b[0]));
​
        // 深拷贝 segments，防止合并区间时修改原始数据
        List<int[]> sortedSegments = new ArrayList<>();
        for (int[] segment : segments) {
            sortedSegments.add(new int[]{segment[0], segment[1]});
        }
​
        // 合并区间
        List<int[]> merged = new ArrayList<>();
        int[] current = sortedSegments.get(0);
        for (int i = 1; i < n; i++) {
            int[] next = sortedSegments.get(i);
            if (next[0] <= current[1]) {
                current[1] = Math.max(current[1], next[1]);
            } else {
                merged.add(current);
                current = next;
            }
        }
        merged.add(current);
​
        // 最小覆盖线段数
        int totalCount = 0;
        for (int[] merge : merged) {
            int L = merge[0], R = merge[1];
            int count = 0;
            int currentPoint = L;
​
            while (currentPoint < R) {
                int best = currentPoint;
                for (int[] segment : segments) {
                    if (segment[0] <= currentPoint && segment[1] > best) {
                        best = segment[1];
                    }
                }
                if (best == currentPoint) {
                    System.out.println(-1);
                    return;
                }
                count++;
                currentPoint = best;
            }
            totalCount += count;
        }
        System.out.println(totalCount);
    }
}
