package main
​
import (
    "fmt"
    "sort"
)
​
func main() {
    var n int
    fmt.Scan(&n)
    segs := make([][2]int, n)
​
    for i := 0; i < n; i++ {
        var a, b int
        fmt.Scanf("%d,%d", &a, &b)
        if a > b {
            a, b = b, a
        }
        segs[i] = [2]int{a, b}
    }
​
    // 按起点排序
    sort.Slice(segs, func(i, j int) bool {
        return segs[i][0] < segs[j][0]
    })
​
    // 合并区间
    var merged [][2]int
    cur := segs[0]
​
    for i := 1; i < n; i++ {
        if segs[i][0] <= cur[1] {
            cur[1] = max(cur[1], segs[i][1])
        } else {
            merged = append(merged, cur)
            cur = segs[i]
        }
    }
    merged = append(merged, cur)
​
    // 计算最少覆盖线段数
    totalCount := 0
​
    for _, M := range merged {
        L, R := M[0], M[1]
        count := 0
        current := L
​
        for current < R {
            best := current
            for _, seg := range segs {
                if seg[0] <= current && seg[1] > best {
                    best = seg[1]
                }
            }
​
            if best == current {
                fmt.Println(-1)
                return
            }
​
            count++
            current = best
        }
​
        totalCount += count
    }
​
    fmt.Println(totalCount)
}
